class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def ok(x):
            total = 0
            prev = 0
            for i in range(n):
                req = (x + points[i] - 1) // points[i]
                rem = req - prev
                if i == n - 1 and rem <= 0:
                    break
                total += 1
                k = rem - 1
                if k > 0:
                    total += 2 * k
                    prev = k
                else:
                    prev = 0
                if total > m:
                    return False
            return total <= m

        lo, hi = 0, max(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
