class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def ok(X):
            total = 0
            carry = 0
            for i in range(n):
                need = (X + points[i] - 1) // points[i]
                if i == n - 1 and need <= carry:
                    break
                rem = need - 1 - carry
                if rem < 0:
                    rem = 0
                total += 1 + 2 * rem
                if total > m:
                    return False
                carry = rem
            return True

        lo, hi = 0, min(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

